let authority_account = account(&program_id, &[0u8; 32], None);

let metas = vec![
    AccountMeta::new_readonly(program_id, false), // placeholder, será substituído
    AccountMeta::new_readonly(authority_key, false),
];

// Baseline: instrução process com treasury legítima
let ix_baseline = env.raw_ix(&[0u8], &[
    AccountMeta::new_readonly(program_id, false),
    AccountMeta::new_readonly(authority_key, false),
]);
let contas_baseline = vec![
    (program_id, treasury_legit.clone()),
    (authority_key, authority_account.clone()),
];
