    AccountMeta::new_readonly(system_program_id, false),
    AccountMeta::new_readonly(authority_key, false),
]);
let contas_attack = vec![
    (system_program_id, treasury_forged.clone()),
    (authority_key, authority_account.clone()),
];
let r_attack = env.attack("process com treasury forjada (owner diferente)", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let after_treasury = after(&r_attack, &system_program_id);
